    for(let i=0;i<35;i++){let x=1+Math.floor(rand()*(cols-2)),y=1+Math.floor(rand()*(rows-2));if(map[y][x]&&((map[y-1][x]===0&&map[y+1][x]===0)||(map[y][x-1]===0&&map[y][x+1]===0)))map[y][x]=0}
  }
