  function newRun(){generateMap();elapsed=0;sprint=100;stun=0;wrongCount=0;juiceReady=false;won=lost=false;quizOpen=false;player={x:tile*1.5,y:tile*1.5,r:11};exit={x:tile*25.5,y:tile*17.5};monitor={x:tile*25.5,y:tile*1.5,r:13,speed:83};juice={x:tile*13.5,y:tile*9.5,got:false};
