  function axisMove(obj,dx,dy,r){if(dx){let nx=obj.x+dx;if(isFloor(Math.floor((nx+(dx>0?r:-r))/tile),Math.floor((obj.y-r+2)/tile))&&isFloor(Math.floor((nx+(dx>0?r:-r))/tile),Math.floor((obj.y+r-2)/tile)))obj.x=nx}if(dy){let ny=obj.y+dy;if(isFloor(Math.floor((obj.x-r+2)/tile),Math.floor((ny+(dy>0?r:-r))/tile))&&isFloor(Math.floor((obj.x+r-2)/tile),Math.floor((ny+(dy>0?r:-r))/tile)))obj.y=ny}}
