      if(interactDown){interactDown=false;if(nearBook)openQuiz(nearBook);else if(nearJuice){juice.got=true;juiceReady=true;$('#objective').innerHTML='JUICE BOX FOUND <b>·</b> PRESS Q TO DISTRACT'}}
      if((keys.has('q')||touch.has('juice'))&&juiceReady&&stun<=0){juiceReady=false;stun=4;touch.delete('juice')}
      if(books.every(b=>b.got)&&distance(player,exit)<35){playing=false;won=true;showEnd(true)}
    }
    pathTimer-=dt;if(pathTimer<=0){pathTimer=.32;path=bfs(Math.floor(monitor.x/tile),Math.floor(monitor.y/tile),Math.floor(player.x/tile),Math.floor(player.y/tile))}
    if(stun<=0&&path.length){let target=path[0],tx=(target.x+.5)*tile,ty=(target.y+.5)*tile,ddx=tx-monitor.x,ddy=ty-monitor.y,d=Math.hypot(ddx,ddy),step=(monitor.speed+Math.min(34,wrongCount*7)+Math.min(20,books.filter(b=>b.got).length*2))*dt;if(d<step+2){monitor.x=tx;monitor.y=ty;path.shift()}else{monitor.x+=ddx/d*step;monitor.y+=ddy/d*step}}
    if(distance(player,monitor)<player.r+monitor.r-2){playing=false;lost=true;showEnd(false)}
    $('#clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;
