function openQuiz(book){quiz={book,...makeQuestion(book.id)};quizOpen=true;$('#question-count').textContent=`BOOK ${book.id+1} / 7`;$('#question-text').textContent=quiz.prompt;$('#quiz-feedback').textContent='';$('#quiz-feedback').className='feedback';$('#answers').innerHTML='';quiz.options.forEach(n=>{let b=document.createElement('button');b.className='answer';b.textContent=n;b.onclick=()=>answer(Number(n));$('#answers').appendChild(b)});$('#quiz-screen').classList.add('visible')}
function makeQuestion(id){let a,b,op,answer;switch(id%4){case 0:a=2+Math.floor(rand()*18);b=2+Math.floor(rand()*17);op='+';answer=a+b;break;case 1:a=3+Math.floor(rand()*20);b=1+Math.floor(rand()*Math.min(15,a-1));op='−';answer=a-b;break;case 2:a=2+Math.floor(rand()*9);b=2+Math.floor(rand()*9);op='×';answer=a*b;break;default:b=2+Math.floor(rand()*8);answer=2+Math.floor(rand()*10);a=b*answer;op='÷'}let vals=new Set([answer]);while(vals.size<3)vals.add(answer+Math.floor(rand()*9)-4);let options=shuffle([...vals].map(String));return{prompt:`${a} ${op} ${b} = ?`,answer,options}}
function answer(value){if(!quizOpen||!quiz)return;if(value===quiz.answer){quiz.book.got=true;let total=books.filter(b=>b.got).length;$('#book-count').textContent=total;$('#progress').style.width=`${total/7*100}%`;[...$('#book-pips').children][total-1]?.classList.add('done');$('#quiz-feedback').textContent=total===7?'Correct! The exit is open.':'Correct! One less notebook to find.';$('#quiz-feedback').className='feedback';setTimeout(()=>{quizOpen=false;$('#quiz-screen').classList.remove('visible');quiz=null},430)}else{wrongCount++;monitor.speed+=11;$('#quiz-feedback').textContent='Not quite. The footsteps are getting closer!';$('#quiz-feedback').className='feedback wrong';[...$('#answers').children].forEach(b=>b.disabled=true);setTimeout(()=>{quizOpen=false;$('#quiz-screen').classList.remove('visible');quiz=null},680)}}
function showEnd(victory){$('#end-eyebrow').textContent=victory?'YOU MADE IT OUT':'RUN ENDED';$('#end-title').innerHTML=victory?'<em>ALL CLEAR.</em>':'CAUGHT.';$('#end-copy').textContent=victory?`Seven notebooks. One very close call. Time: ${$('#clock').textContent}.`:'The hall monitor found you. Take a breath, then try another route.';$('#end-screen').classList.add('visible')}
function draw(){ctx.clearRect(0,0,W,H);const camX=Math.max(0,Math.min(cols*tile-W,player.x-W/2)),camY=Math.max(0,Math.min(rows*tile-H,player.y-H/2));ctx.save();ctx.translate(-camX,-camY);
  let x0=Math.max(0,Math.floor(camX/tile)),x1=Math.min(cols,Math.ceil((camX+W)/tile)),y0=Math.max(0,Math.floor(camY/tile)),y1=Math.min(rows,Math.ceil((camY+H)/tile));
  for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let px=x*tile,py=y*tile;if(map[y][x]===0){ctx.fillStyle=((x+y)%2)?'#42483c':'#474c40';ctx.fillRect(px,py,tile,tile);ctx.strokeStyle='#525648';ctx.lineWidth=1;ctx.strokeRect(px+4,py+4,tile-8,tile-8);if((x*13+y*7)%11===0){ctx.fillStyle='#77745c';ctx.fillRect(px+12,py+17,3,2);ctx.fillRect(px+31,py+32,2,2)}}else{ctx.fillStyle='#252d25';ctx.fillRect(px,py,tile,tile);ctx.fillStyle='#59604d';ctx.fillRect(px+1,py+1,tile-2,4);ctx.fillStyle='#374034';ctx.fillRect(px+2,py+6,tile-4,tile-8);ctx.fillStyle='#202720';ctx.fillRect(px+2,py+tile-3,tile-4,2);ctx.fillStyle='#444b3e';ctx.fillRect(px+8,py+12,tile-16,2)}}
  // Classroom accents and corridor signs
  drawDesk(3.5*tile,3.5*tile);drawDesk(7.5*tile,13.5*tile);drawDesk(19.5*tile,5.5*tile);drawDesk(15.5*tile,15.5*tile);
  if(books.every(b=>b.got))drawExit(exit.x,exit.y);else drawExit(exit.x,exit.y,true);
  if(!juice.got)drawJuice(juice.x,juice.y);
  for(let b of books)if(!b.got)drawBook(b.x,b.y);
  drawMonitor(monitor.x,monitor.y);drawPlayer(player.x,player.y);
